from typing import List, Dict, Callable

# 预定义约束检查函数注册
CONSTRAINT_CHECKERS = {}

def register_checker(name: str):
    def decorator(func):
        CONSTRAINT_CHECKERS[name] = func
        return func
    return decorator

@register_checker('word_count_between')
def check_word_count(text: str, params: dict) -> bool:
    words = text.split()
    return params.get('min', 0) <= len(words) <= params.get('max', float('inf'))

@register_checker('must_contain')
def check_must_contain(text: str, params: dict) -> bool:
    return params['substring'] in text

@register_checker('forbidden_words')
def check_forbidden_words(text: str, params: dict) -> bool:
    return all(word not in text for word in params.get('words', []))

@register_checker('json_format')
def check_json(text: str, params=None) -> bool:
    try:
        json.loads(text.strip())
        return True
    except:
        return False

def ifeval_evaluate(responses: List[str], constraints_list: List[List[Dict]]) -> float:
    """
    responses: 模型生成的回答列表
    constraints_list: 每条指令对应的约束列表，每个约束是一个字典 {'type': ..., 'params': {...}}
    返回严格约束遵循率
    """
    total = len(responses)
    strict_correct = 0
    for resp, constraints in zip(responses, constraints_list):
        if all(CONSTRAINT_CHECKERS[c['type']](resp, c.get('params', {})) for c in constraints):
            strict_correct += 1
    return strict_correct / total if total > 0 else 0.0
